import json
from pathlib import Path
P=Path(__file__).parent
D=json.loads((P/'content.json').read_text()); R={r['id']:r for r in D['results']}
COMMON_ZH=r'''固定有限总体 $N=\{1,\ldots,n\}$、输入 $x$、输入基线向量 $r$ 和实值模型 $v$。掩码 $x_U$ 保留 $U$ 中坐标，其余置为 $r$；$g(U)=v(x_U)$，输出基线 $b=g(\varnothing)$。输入基线原记 $b_i$，与此处标量 $b$ 不同。选择同一个分解函数 $\gamma$，令 $a(U)=g(U)/2+\gamma_U$、$o(U)=g(U)/2-\gamma_U$，故 $a+o=g$。AND 分量交互 $A(S)=\sum_{U\subseteq S}(-1)^{|S|-|U|}a(U)$；非空 OR 分量交互 $O(S)=-\sum_{U\subseteq S}(-1)^{|S|-|U|}o(N\setminus U)$。原始总输出的交互 $I_g$ 与分量 $A$ 不混同。'''
COMMON_EN=r'''Fix the finite universe $N=\{1,\ldots,n\}$, input $x$, input baseline vector $r$, and a real-valued model $v$. The mask $x_U$ retains coordinates in $U$ and sets the others to $r$; write $g(U)=v(x_U)$ and output baseline $b=g(\varnothing)$. The source input baseline $b_i$ is distinct from this scalar $b$. Choose one decomposition function $\gamma$ and put $a(U)=g(U)/2+\gamma_U$, $o(U)=g(U)/2-\gamma_U$, so that $a+o=g$. The AND component dividend is $A(S)=\sum_{U\subseteq S}(-1)^{|S|-|U|}a(U)$; the nonempty OR component dividend is $O(S)=-\sum_{U\subseteq S}(-1)^{|S|-|U|}o(N\setminus U)$. The raw total-output dividend $I_g$ and component dividend $A$ remain distinct.'''
def setr(id,title,en_title,formula,original,overview,en_overview,assumptions=(),en_assumptions=(),defs=(),en_defs=(),status='complete',scope=None,en_scope=None,issues=()):
 r=R[id];r.update(title=title,statement_tex=formula,original_statement_md=original,original_statement_source_type='formal_mathematical_transcription_with_project_chinese_translation',overview=overview,assumptions=list(assumptions),definitions=[{'id':i,'body_md':z} for i,z in defs],rewrite_status=status,alignment_status='agent_reviewed_original_statement_preserved',proof_steps=[],related_issue_ids=list(issues),symbol_ids=['model-output','masked-input','set-game','output-baseline','input-baseline','layer-and-component','layer-or-component','layer-gamma','layer-and-interaction','layer-or-interaction'],notation_map=[{'source':r'v(x_T)','canonical':r'g(T)=v(x_T)','meaning':'同一固定输入和输入基线的掩码游戏。'},{'source':r'b_i','canonical':r'r_i','meaning':'输入基线坐标，不能换成输出基线标量。'}])
 if r['original_proof_source_type'] in ('source_transcription_in_progress','no_local_proof'):
  r['original_proof_source_type']='no_local_author_proof';r['original_proof_md']='此处原文没有独立作者证明；以下是项目重写或定义解释，不冒充作者原证明。'
 r['original_statement_note']='公式按正式 PDF 转录；说明文字为项目中文译述，原页版面是权威来源。'
 r['lean']={'status':'not_reported','declarations':[],'compiled':False,'scope':'This content does not claim formal verification before a current declaration report is bound.'}
 r['translations']={'en':{'title':en_title,'overview':en_overview,'assumptions':list(en_assumptions),'definitions':[{'id':i,'body_md':z} for i,z in en_defs],'proof_steps':[],'notation_map':[{'source':r'v(x_T)','canonical':r'g(T)=v(x_T)','meaning':'The masked game uses the same fixed input and input baseline.'},{'source':r'b_i','canonical':r'r_i','meaning':'An input baseline coordinate, distinct from the scalar output baseline.'}],'original_statement_note':'Equations are transcribed from the formal PDF; the explanatory Chinese prose is a project rendering, while the original page is the authoritative layout.'}}
 if scope:r['proof_scope']=scope;r['translations']['en']['proof_scope']=en_scope
 return r

def step(r,title,en_title,body,en_body,formula='',why='',en_why='',refs=()):
 k=len(r['proof_steps'])+1;sid=r['id']+'-step-'+str(k)
 r['proof_steps'].append({'id':sid,'title':title,'body_md':body,'formula_tex':formula,'justification':why,'lean_refs':list(refs)})
 r['translations']['en']['proof_steps'].append({'id':sid,'title':en_title,'body_md':en_body,'justification':en_why})

def refs(name,zh,en,scope='exact_declaration_pending_current_report'):
 return [{'declaration':name,'source_path':'lean/HarsanyiLib/Harsanyi/Extensions/LayerwiseKnowledge.lean','scope':scope,'explanation_md':zh}]

def flush():
 import runpy
 runpy.run_path(str(P.parent/'shared_dependencies.py'))['apply_shared_dependencies'](D,P)
 D['issues']=json.loads((P/'issues.json').read_text()).get('issues',[])
 D['symbols']=json.loads((P/'symbols.json').read_text()).get('symbols',[])
 (P/'content.json').write_text(json.dumps(D,ensure_ascii=False,indent=2)+'\n')

r=setr('layer-and-definition','Definition 3.1：原始输出的 AND 交互','Definition 3.1: AND dividends of the raw output',r'I_g(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}v(x_T)',r'''原 Eq.(1)：$I_{and}(S\mid x)=\sum_{T\subseteq S}(-1)^{|S|-|T|}v(x_T)$，其中 $S\subseteq N$。紧随原式的重构为 $v(x)=\sum_{S\subseteq N}I_{and}(S\mid x)$。''','交互是有限集合上的 Möbius 变换，空集保存原始输出基线。','The dividend is the Möbius transform on a finite set lattice, and its empty term retains the raw output baseline.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)])
step(r,'展开掩码与交互','Expand masks and the dividend',r'''每项 $v(x_T)$ 使用相同 $x,r$。对 $S=\varnothing$，仅有 $T=\varnothing$，符号为 $1$，故 $I_g(\varnothing)=b$；对单点 $S=\{i\}$，$I_g(S)=g(\{i\})-b$。这是定义的边界核对，不预设零基线。''',r'''Every $v(x_T)$ uses the same $x,r$. If $S=\varnothing$, the sole summand is $T=\varnothing$ with sign $1$, hence $I_g(\varnothing)=b$. For $S=\{i\}$, $I_g(S)=g(\{i\})-b$. These checks establish the definition's boundary cases without assuming a zero baseline.''',r'I_g(\varnothing)=b,\qquad I_g(\{i\})=g(\{i\})-b.')
step(r,'区分原始交互与分量交互','Distinguish raw and component dividends',r'''第 4 页沿用 $I_{and}$ 表示 $v_{and}$ 的变换，输入已从 $g$ 换成 $a$。因此 $I_g$ 与 $A$ 是不同实例；只有 $a=g$ 时才逐项相同。先确定作用域，之后才能使用重构或比较层间系数。''',r'''Page 4 reuses $I_{and}$ for the transform of $v_{and}$, replacing the input game $g$ by $a$. Thus $I_g$ and $A$ are different instances; they agree term by term when $a=g$. The scope must be identified before reconstruction or layerwise comparisons are used.''')

r=setr('layer-and-reconstruction','AND 交互重构全部掩码输出','AND dividends reconstruct every masked output',r'g(T)=\sum_{S\subseteq T}I_g(S)\quad(T\subseteq N)',r'''第 3 页在 Eq.(1) 后写 $v(x)=\sum_{S\subseteq N}I_{and}(S\mid x)$。附录 F 的 Eq.(15) 对同一 Möbius 变换给出任意保留集 $T$ 的重构计算。''','交换有限双重求和，再按剩余坐标的子集数消去。','Exchange the finite double sum and cancel by the number of subsets of the remaining coordinates.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)],issues=['layer-issue-binomial-15'])
r['original_proof_md']='原文计算是附录 F 原证明的 AND 部分 Eq.(15)，完整转录由 layer-universal-matching.original_proof_md 与对应 original-proofs 文件提供；本条不把节选或项目补全标为独立完整作者证明。';r['original_proof_source_type']='author_proof_component_in_parent_full_transcription';r['original_proof_parent_result_id']='layer-universal-matching'
step(r,'交换有限双重求和','Exchange the finite double sum',r'''将 $I_g(S)$ 定义代入。对于固定 $L\subseteq T$，包含它的 $S$ 唯一写为 $L\cup U$，其中 $U\subseteq T\setminus L$，且 $|S|-|L|=|U|$。''',r'''Substitute the definition of $I_g(S)$. For fixed $L\subseteq T$, every containing $S$ has the unique form $L\cup U$ with $U\subseteq T\setminus L$, and $|S|-|L|=|U|$.''',r'\sum_{S\subseteq T}I_g(S)=\sum_{L\subseteq T}g(L)\sum_{U\subseteq T\setminus L}(-1)^{|U|}.')
step(r,'按子集数补全二项式系数','Restore the binomial multiplicities',r'''令 $k=|T|-|L|$。大小为 $j$ 的剩余子集有 $\binom{k}{j}$ 个，所以内和是 $\sum_{j=0}^{k}\binom{k}{j}(-1)^j=(1-1)^k$，并非原 Eq.(15) 漏掉系数的 $\sum_{j=0}^{k}(-1)^j$。$L=T$ 时内和为 $1$，否则为 $0$，故只剩 $g(T)$；$T=\varnothing$ 同样成立。''',r'''Put $k=|T|-|L|$. There are $\binom{k}{j}$ remaining subsets of size $j$, so the inner sum is $\sum_{j=0}^{k}\binom{k}{j}(-1)^j=(1-1)^k$, rather than the coefficient-free $\sum_{j=0}^{k}(-1)^j$ printed in Eq.(15). It is $1$ if $L=T$ and $0$ otherwise, leaving $g(T)$. The empty $T$ case also holds.''',r'\sum_{j=0}^{k}\binom{k}{j}(-1)^j=\begin{cases}1&k=0,\\0&k>0.\end{cases}')

r=setr('layer-decomposition','AND/OR 分量与可学习分解','AND/OR components and the learned split',r'a(T)=\tfrac12g(T)+\gamma_T,\quad o(T)=\tfrac12g(T)-\gamma_T,\quad a(T)+o(T)=g(T)',r'''第 3–4 页：$v_{and}(x_T)=0.5v(x_T)+\gamma_T$、$v_{or}(x_T)=0.5v(x_T)-\gamma_T$；学习 $\{\gamma_T\}$ 以得到稀疏分解。Theorem 3.3 另明确规定空集分量 $v_{and}(x_\varnothing)=v(x_\varnothing)$、$v_{or}(x_\varnothing)=0$。''','点态恒等式成立，但总游戏并不唯一决定分量交互。','The pointwise identity holds, while the total game does not uniquely determine component dividends.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)])
step(r,'核对分量和与空集约束','Check the component sum and empty constraint',r'''两分量中 $\gamma_T$ 抵消，得到 $a(T)+o(T)=g(T)$。定理原有的空集条件等价于 $\gamma_\varnothing=b/2$；因而 $A(\varnothing)=b$，OR 的特设空集值为 $o(\varnothing)=0$。这些条件来自原定理，并非项目新加。''',r'''The two occurrences of $\gamma_T$ cancel, yielding $a(T)+o(T)=g(T)$. The theorem's stated empty-set conditions are equivalent to $\gamma_\varnothing=b/2$. Consequently $A(\varnothing)=b$, and the special empty OR value is $o(\varnothing)=0$. These conditions are in the source theorem.''',r'a(\varnothing)=b,\ o(\varnothing)=0\ \Longleftrightarrow\ \gamma_\varnothing=b/2.',refs=refs('Harsanyi.Layerwise.component_empty','实际声明核对原定理空集分解条件。','The declaration checks the source theorem’s empty split.'))
step(r,'说明优化与非唯一性','Explain optimization and nonuniqueness',r'''第 4 页外引分解学习方法，没有在此给出优化问题的唯一解定理。第 5 页同时优化 $\gamma$ 与有界残差 $\delta_T$，最小化交互绝对值总和。固定学习结果后才能比较它的分量；不同学习结果不能只因总输出相同就视为同一交互表示。''',r'''Page 4 cites an external split-learning method and supplies no uniqueness theorem here. Page 5 jointly optimizes $\gamma$ and bounded residuals $\delta_T$ to minimize the sum of absolute interaction effects. A comparison concerns a fixed learned split; two learning outcomes are not the same dividend representation merely because their total output agrees.''')

r=setr('layer-or-definition','Definition 3.2：非空 OR 交互与特设空集','Definition 3.2: nonempty OR dividends and the special empty value',r'O(S)=-\sum_{T\subseteq S}(-1)^{|S|-|T|}o(N\setminus T)\quad(S\ne\varnothing),\qquad O(\varnothing)=o(\varnothing)',r'''原 Eq.(2) 不加非空限定写 $I_{or}(S\mid x)=-\sum_{T\subseteq S}(-1)^{|S|-|T|}v_{or}(x_{N\setminus T})$。随后 Theorem 3.3 对空集另外规定 $I_{or}(\varnothing\mid x)=v_{or}(x_\varnothing)=0$。''','OR 是补集游戏的负 Möbius 变换；空集使用原定理的独立约定。','OR is the negative Möbius transform of the complementary game; the empty term uses the theorem’s separate convention.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)],status='complete_with_scope_issue',scope='原 Eq.(2) 在空集的字面代入是 −o(N)，不能与原定理的特设空集值混同；非空定义和原定理空集约定分别保存。',en_scope='Literal substitution of the empty set in Eq.(2) gives −o(N), which is distinct from the theorem’s special empty value. The nonempty definition and stated empty convention are recorded separately.',issues=['layer-issue-empty-or'])
step(r,'构造补集游戏','Construct the complementary game',r'''令 $h(T)=o(N\setminus T)$。对于非空 $S$，定义立即给出 $O(S)=-I_h(S)$。单点例子为 $O(\{i\})=o(N)-o(N\setminus\{i\})$；该系数在保留集与 $\{i\}$ 相交时激活。''',r'''Let $h(T)=o(N\setminus T)$. For nonempty $S$, the definition immediately gives $O(S)=-I_h(S)$. For a singleton, $O(\{i\})=o(N)-o(N\setminus\{i\})$; this coefficient activates when the retained set meets $\{i\}$.''',r'O(S)=-I_h(S),\quad h(T)=o(N\setminus T)\quad(S\ne\varnothing).')
step(r,'保留空集定义差异','Retain the empty-set distinction',r'''若机械套用 Eq.(2) 到空集，会得到 $-o(N)$。而重构中的基线是 $o(\varnothing)$。例如 $N=\{1\}$、$o(\varnothing)=0$、$o(N)=1$，两个值为 $-1$ 与 $0$。因此空集不能靠统一公式或 Lean 的实现约定消除差异，来源问题单列。''',r'''Applying Eq.(2) mechanically to the empty set gives $-o(N)$, whereas the reconstruction baseline is $o(\varnothing)$. For instance, if $N=\{1\}$, $o(\varnothing)=0$, and $o(N)=1$, the two values are $-1$ and $0$. A uniform formula or a Lean convention cannot erase this source discrepancy.''')

r=setr('layer-universal-matching','Theorem 3.3：AND/OR 普遍匹配','Theorem 3.3: universal AND/OR matching',r'g(T)=\sum_{S\subseteq T}A_T(S)+\sum_{\substack{S\subseteq N\\S\cap T\ne\varnothing}}O_T(S)\quad(T\subseteq N)',r'''原 Theorem 3.3 / Eqs.(3),(14)：$v(x_T)=v_{and}(x_T)+v_{or}(x_T)=\sum_{S\subseteq T}I_{and}(S\mid x_T)+\sum_{S\cap T\ne\varnothing}I_{or}(S\mid x_T)$，原条件为 $I_{and}(\varnothing\mid x)=v_{and}(x_\varnothing)=v(x_\varnothing)$、$I_{or}(\varnothing\mid x)=v_{or}(x_\varnothing)=0$。''','用 Möbius 反演分别重构 AND 和 OR；原有条件式与固定式都核对，不能混换 OR 系数。','Reconstruct the AND and OR components by Möbius inversion, checking both the source’s conditional form and the fixed form without interchanging their OR coefficients.',assumptions=[r'$T\subseteq N$；原定理规定 $a(\varnothing)=b$、$o(\varnothing)=0$，即 $\gamma_\varnothing=b/2$。'],en_assumptions=[r'$T\subseteq N$; the source theorem stipulates $a(\varnothing)=b$, $o(\varnothing)=0$, equivalently $\gamma_\varnothing=b/2$.'],defs=[('layer-objects',COMMON_ZH),('layer-conditional-game',r'''原式的 $x_T$ 条件游戏按再次掩码解释：$g_T(U)=g(T\cap U)$，$\gamma_T(U)=\gamma(T\cap U)$，分量 $a_T,o_T$ 同样限制。$A_T=I_{a_T}$；非空 $O_T(S)=-I_{U\mapsto o_T(N\setminus U)}(S)$。同一分解必须沿掩码限制；重新独立学习分解是另一实例。''')],en_defs=[('layer-objects',COMMON_EN),('layer-conditional-game',r'''Read the source conditioning on $x_T$ as repeated masking: $g_T(U)=g(T\cap U)$ and $\gamma_T(U)=\gamma(T\cap U)$, with similarly restricted components $a_T,o_T$. Put $A_T=I_{a_T}$ and, for nonempty $S$, $O_T(S)=-I_{U\mapsto o_T(N\setminus U)}(S)$. The same split is restricted along the mask; independently relearning it defines another instance.''')],issues=['layer-issue-binomial-15','layer-issue-or-calculation-16','layer-issue-conditional-scope'])
step(r,'重构 AND 并补全二项式计数','Reconstruct AND with the missing binomial counts',r'''对任意有限游戏 $a$，交换有限和得 $\sum_{S\subseteq T}A(S)=\sum_{L\subseteq T}a(L)\sum_{U\subseteq T\setminus L}(-1)^{|U|}=a(T)$。每个大小为 $j$ 的 $U$ 有 $\binom{|T|-|L|}{j}$ 种，故内和按二项式定理消去。原 Eq.(15) 漏掉此系数，项目在同一命题下补全。''',r'''For any finite game $a$, exchanging finite sums gives $\sum_{S\subseteq T}A(S)=\sum_{L\subseteq T}a(L)\sum_{U\subseteq T\setminus L}(-1)^{|U|}=a(T)$. Each size $j$ occurs $\binom{|T|-|L|}{j}$ times, so the binomial theorem cancels the inner sum. Eq.(15) omits this coefficient; the project restores it for the same claim.''',r'\sum_{S\subseteq T}A(S)=a(T).')
step(r,'用补集反演重构 OR','Reconstruct OR by complementary inversion',r'''令 $h(U)=o(N\setminus U)$。Möbius 反演给 $\sum_{S\subseteq N,S\ne\varnothing}O(S)=o(N)-o(\varnothing)$，并给 $\sum_{S\subseteq N\setminus T,S\ne\varnothing}O(S)=o(N)-o(T)$。相减后仅保留与 $T$ 相交的集合，得到 $\sum_{S\cap T\ne\varnothing}O(S)=o(T)-o(\varnothing)$。这条完整消去也避免直接沿用原 Eq.(16) 的分组符号：按其 $S_2$ 含 $T\cap L$ 的写法，正确指数应扣除 $|T\cap L|$；原式没有扣除。零因子的证明还须同时核对两个剩余块，不能只检查其中一个。''',r'''Set $h(U)=o(N\setminus U)$. Möbius inversion gives $\sum_{S\subseteq N,S\ne\varnothing}O(S)=o(N)-o(\varnothing)$ and $\sum_{S\subseteq N\setminus T,S\ne\varnothing}O(S)=o(N)-o(T)$. Subtracting retains exactly the sets meeting $T$, yielding $\sum_{S\cap T\ne\varnothing}O(S)=o(T)-o(\varnothing)$. This full cancellation also avoids Eq.(16)’s printed signs: because its $S_2$ contains $T\cap L$, the exponent must subtract $|T\cap L|$, which the source omits. A zero-factor proof must check both remaining blocks, rather than just one.''',r'\sum_{\substack{S\subseteq N\\S\cap T\ne\varnothing}}O(S)=o(T)-o(\varnothing).')
step(r,'合成固定游戏与条件游戏','Combine the fixed and conditional games',r'''固定式由 $a+o=g$ 及 $o(\varnothing)=0$ 立即得到。再对游戏 $g_T$ 及限制分解使用同一反演：$g_T(T)=g(T)$，$a_T(\varnothing)=b$、$o_T(\varnothing)=0$，于是得到原条件式。若 $S\subseteq T$，$A_T(S)=A(S)$，因为其全部子集 $U$ 满足 $T\cap U=U$；OR 补集项通常不同，不能照此替换。若对 $x_T$ 独立重新学习自由分解，则直接对新分解使用同一通用重构定理，并核对它的原空项约定即可；不能假设新优化结果必等于旧 $\gamma$ 的限制。当前 conditional 声明只编码固定分解的再次掩码适配，base and_or_matching 可另实例化新分解。''',r'''The fixed formula follows from $a+o=g$ and $o(\varnothing)=0$. Apply the same inversion to $g_T$ and the restricted split: $g_T(T)=g(T)$, $a_T(\varnothing)=b$, and $o_T(\varnothing)=0$, which gives the source’s conditional formula. If $S\subseteq T$, then $A_T(S)=A(S)$ because every subcoalition $U$ satisfies $T\cap U=U$. OR complementary terms generally differ and cannot be replaced by the same argument. If a free split is independently relearned for $x_T$, apply the same reconstruction theorem directly to that new split and check its stated empty convention; the new optimizer need not equal the old $\gamma$ restricted to the mask. The current conditional declaration encodes restriction of a fixed split, whereas base and_or_matching can be separately instantiated with the new split.''',r'g(T)=\sum_{S\subseteq T}A(S)+\sum_{S\cap T\ne\varnothing}O(S)=\sum_{S\subseteq T}A_T(S)+\sum_{S\cap T\ne\varnothing}O_T(S).',refs=refs('Harsanyi.Layerwise.conditional_and_or_matching','本声明对应原条件游戏的最终恒等式；文字中两段反演并未分别声明独立形式化。','This declaration is the final conditional-game equality; the two inversion paragraphs are not separately claimed as formal declarations.'))
step(r,'核对空集与非零基线','Check the empty mask and a nonzero baseline',r'''当 $T=\varnothing$，OR 激活和为空，AND 和仅有 $A_T(\varnothing)=b$。一般 $T$ 的空集 AND 项已经贡献 $b$；如果另写显式基线，必须把 AND 求和改为非空集合。无需假设 $b=0$。''',r'''When $T=\varnothing$, the active OR sum is empty, and the AND sum consists of $A_T(\varnothing)=b$. For general $T$, the empty AND term already contributes $b$; an explicit baseline requires removing it from the AND sum. No assumption $b=0$ is needed.''')
flush()

r=setr('layer-salient-matching','Lemma 3.4：显著交互近似与外引范围','Lemma 3.4: salient approximation and external scope',r'g(T)\approx b+\sum_{\substack{S\in\Omega_{and}\\\varnothing\ne S\subseteq T}}A_T(S)+\sum_{\substack{S\in\Omega_{or}\\S\cap T\ne\varnothing}}O_T(S)',r'''原 Lemma 3.4 / Eqs.(4),(18)：对输入 $x\in\mathbb R^n$，全部 $2^n$ 掩码输出可以用小集合显著交互普遍匹配。附录 G 外引 Ren 等关于某些共同条件下 AND 稀疏性的结果，再通过附录 C 推断 OR 稀疏。原文未给本引理近似误差的数值界或“小”的定量阈值。''','修复重复基线，再明确精确重构与“小集合近似”的逻辑间隔。','Repair the duplicate baseline and identify the logical gap between exact reconstruction and approximation by a small family.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)],status='complete_with_scope_issue',scope='完整原论证和范围审查已给出。原引理的无量化“小/近似”和两个学习分量的外引条件未验证，不能宣称原引理已被证明或完整形式化。尾和界是独立条件性结果，不替代原命题。',en_scope='The full author argument and scope review are supplied. The unquantified smallness/approximation and external assumptions for both learned components remain unverified, so the original lemma is not claimed proved or fully formalized. The tail bound is a separate conditional result.',issues=['layer-issue-baseline-19','layer-issue-sparse-transfer'])
step(r,'修复重复输出基线','Repair the duplicate output baseline',r'''原 Eq.(19) 在 $\sum_{S\subseteq T}A_T(S)$ 前又加 $b$，而空集项已经等于 $b$。保留显式基线时必须改成非空 AND 和，才能与 Theorem 3.3 相等。取常数游戏 $g=1$、$a=1$、$o=0$，原式右端是 $2$、左端是 $1$；这是原中间等式错误，不是稀疏近似本身的反例。''',r'''Eq.(19) adds $b$ before $\sum_{S\subseteq T}A_T(S)$ although its empty term already equals $b$. Keeping an explicit baseline requires the nonempty AND sum to recover Theorem 3.3. For the constant game $g=1$, $a=1$, $o=0$, the printed right side is $2$ and the left side is $1$. This refutes the intermediate equality, rather than the sparse approximation itself.''',r'g(T)=b+\sum_{\varnothing\ne S\subseteq T}A_T(S)+\sum_{S\cap T\ne\varnothing}O_T(S).',refs=refs('Harsanyi.Layerwise.duplicated_baseline_counterexample','声明仅核验常数游戏重复基线这一原式错误。','The declaration checks only the duplicate-baseline error in the constant game.'))
step(r,'逐项推导被省略尾和界','Derive the omitted-tail bound term by term',r'''对任意指定集合族 $\Omega_{and},\Omega_{or}$，精确式减去近似式，差恰是被省略的激活项之和。三角不等式给下式。若对所有 $T$ 的省略绝对值尾和有统一界 $\varepsilon$，才得到误差不超过 $\varepsilon$ 的普遍近似。仅有每项小或个数少，没有控制总尾和，不能自动推出该界。''',r'''For any specified families $\Omega_{and},\Omega_{or}$, subtract the approximation from the exact identity. The difference is exactly the sum of omitted active terms. The triangle inequality gives the displayed bound. A uniform tail bound $\varepsilon$ for all $T$ then gives universal error at most $\varepsilon$. Small individual terms or a small retained count alone do not automatically control the total tail.''',r'|g(T)-\widehat g(T)|\le\sum_{\substack{\varnothing\ne S\subseteq T\\S\notin\Omega_{and}}}|A_T(S)|+\sum_{\substack{S\cap T\ne\varnothing\\S\notin\Omega_{or}}}|O_T(S)|.')
step(r,'审查外引条件而非增加假设','Audit the cited conditions without adding assumptions',r'''第 3 页脚注列出的外引条件包括模型不编码极高阶交互、平均输出随保留变量数单调增加、少量遮罩不会显著改变平均输出。第 4 页正文还明确说同时使用 AND/OR 的稀疏性尚未证明。学习得到的 $a,o$ 未被证明满足这些条件；补集变换也不能自动保留它们。因此附录 G 的结论缺少这层验证。保留原引理及其原条件，只登记范围缺口，不把新尾和条件写入原命题。''',r'''Footnote 1 on page 3 lists conditions concerning the absence of extremely high-order interactions, monotonicity of mean output with retained input count, and limited change of mean output under a few masks. Page 4 also explicitly says simultaneous AND/OR sparsity has not been proved. Neither learned component $a,o$ is shown to satisfy those conditions, and complementing a game does not automatically preserve them. Appendix G lacks this verification. The original claim and conditions are retained; the new tail condition is not inserted into the source proposition.''')

r=setr('layer-probe-definition','线性探针、残差与层输出定义','Linear probes, residuals, and the layer output',r'p^{(l)}(y\mid x)=\operatorname{softmax/sigmoid}((w^{(l)})^{\mathsf T}f^{(l)}(x)+b^{(l)}),\quad v^{(l)}(x_T)=\log\frac{p^{(l)}(y^{truth}\mid x_T)}{1-p^{(l)}(y^{truth}\mid x_T)}-\delta_T',r'''原 Eq.(5) 分别写完整输入和掩码输入的 log-odds 减残差；$|\delta_T|<\kappa$，$\kappa=0.04|v^{(l)}(x_N)-v^{(l)}(x_\varnothing)|$。原文训练线性分类器时固定原 DNN 参数，同时优化 $\gamma_T,\delta_T$ 以减少交互绝对值总和。Appendix J Eq.(20) 重述残差设置。''','层间比较使用同任务探针的标量分数，残差是确定性学习参数。','Layer comparisons use a scalar score from a probe for the same task; residuals are deterministic learned parameters.',defs=[('layer-probe-objects',r'''$f^{(l)}$ 是固定 DNN 的第 $l$ 层特征；$w^{(l)},b^{(l)}$ 是另行训练的线性探针参数。$b^{(l)}$ 是分类器截距，既不是输入基线 $r$，也不是掩码输出基线 $b_l=v^{(l)}(x_\varnothing)$。$\delta_T$ 不是随机高斯噪声。''')],en_defs=[('layer-probe-objects',r'''$f^{(l)}$ is layer $l$ of the fixed DNN; $w^{(l)},b^{(l)}$ are separately trained linear-probe parameters. The intercept $b^{(l)}$ is distinct from input baseline $r$ and masked output baseline $b_l=v^{(l)}(x_\varnothing)$. The residual $\delta_T$ is not Gaussian random noise.''')])
step(r,'规定有限实数分数的定义域','Specify the domain of a finite real score',r'''log-odds 需要 $0<p^{(l)}(y^{truth}\mid x_T)<1$。有限 logits 的 sigmoid、至少两类有限 logits 的 softmax 满足此条件；概率为 $0$ 或 $1$ 时原对数不再是有限实数。每层独立定义 $g_l(T)=v^{(l)}(x_T)$，而不是把向量特征直接当作实值游戏。''',r'''Finite log-odds requires $0<p^{(l)}(y^{truth}\mid x_T)<1$. A sigmoid with finite logits, and a softmax with at least two finite logits, satisfy this condition; probabilities $0$ or $1$ do not yield finite real logarithms. Define $g_l(T)=v^{(l)}(x_T)$ separately at each layer, rather than treating a vector feature as a real-valued game.''')
step(r,'说明残差限制和学习范围','Explain the residual constraint and learning scope',r'''在给定可行残差下，交互是游戏 $g_l$ 的精确有限变换；残差选择可能改变每个变换系数。$\kappa=0$ 时严格条件 $|\delta_T|<0$ 没有可行解，原文未给零差值的另行约定。附录 J 比较 $0.03,0.04,0.05$ 三个比例的经验稳健性，不能把它写成任意比例都稳健的定理。''',r'''For a feasible residual choice, dividends are exact finite transforms of $g_l$; choosing residuals may change every coefficient. If $\kappa=0$, the strict constraint $|\delta_T|<0$ is infeasible, and the source gives no separate zero-difference convention. Appendix J empirically compares the three factors $0.03,0.04,0.05$; it does not establish robustness for arbitrary factors.''')
step(r,'保留探针解释的局限','Retain the limitations of the probe interpretation',r'''附录 D 承认探针性能依赖可分离结构、分类器复杂度、数据集覆盖和输入基线；探针与原网络决策链也可能不同。因此这些交互刻画探针可用于分类的信号，不能从定义推出它们等同于人类知识或原网络全部因果计算。''',r'''Appendix D acknowledges dependence on separable structure, classifier complexity, dataset coverage, and input baseline; a probe may also differ from the original network’s decision pathway. These dividends describe signals the probe can use for classification. Their definition alone does not identify them with human knowledge or all causal computations of the original network.''')

METRIC_ZH=r'''写 $A_l(S),O_l(S)$ 表示固定样本的第 $l$ 层分量交互。阶数为 $|S|$。脚注 7 取 $\tau_l=0.05\max_{S}\max\{|A_l(S)|,|O_l(S)|\}$，$\Omega_{and}^{l,m}=\{S\subseteq N:|S|=m,|A_l(S)|>\tau_l\}$，OR 类似。附录 M.4 的稀疏性实验另取跨样本最大值，不能与脚注 7 单样本阈值混同。脚注 8 用 $c_l=\mathbb E_x|g_l(N)-g_l(\varnothing)|$ 除该层全部交互；$c_l=0$ 时此归一化未定义。共享系数 $s(a,b)$ 在异号时为 $0$，同号时是 $\operatorname{sign}(a)\min(|a|,|b|)$；零值时为 $0$。'''
METRIC_EN=r'''Write $A_l(S),O_l(S)$ for the fixed sample’s component dividends at layer $l$. Order is $|S|$. Footnote 7 uses $\tau_l=0.05\max_{S}\max\{|A_l(S)|,|O_l(S)|\}$ and $\Omega_{and}^{l,m}=\{S\subseteq N:|S|=m,|A_l(S)|>\tau_l\}$, with the analogous OR family. Appendix M.4 instead uses a maximum across samples for its sparsity experiment, which is distinct from footnote 7’s sample-specific threshold. Footnote 8 divides all layer dividends by $c_l=\mathbb E_x|g_l(N)-g_l(\varnothing)|$; this is undefined when $c_l=0$. The shared coefficient $s(a,b)$ is $0$ for opposite signs and $\operatorname{sign}(a)\min(|a|,|b|)$ for the same sign, with value $0$ at a zero argument.'''
r=setr('layer-metric-definition','交互强度、显著集合、IoU 与稳定性指标','Strength, salient families, IoU, and stability metrics',r'\operatorname{all}_{l,m}=\sum_{S\in\Omega_{and}^{l,m}}|A_l(S)|,\quad\operatorname{IoU}(\mathcal A,\mathcal B)=\frac{|\mathcal A\cap\mathcal B|}{|\mathcal A\cup\mathcal B|}',r'''Eqs.(6),(7) 定义显著交互总强度、共享/忘记/新增强度；Eq.(9) 定义不同模型显著集合的交并比；Eqs.(10),(21) 定义噪声下交互均值绝对值与标准差之比的平均。附录 H 汇总指标；脚注 7、8 和附录 M.4 规定阈值和归一化。''','全部指标保留求和域、层标记、阈值和零分母边界。','Every metric retains its summation domain, layer labels, threshold, and zero-denominator boundary.',defs=[('layer-objects',COMMON_ZH),('layer-metric-objects',METRIC_ZH)],en_defs=[('layer-objects',COMMON_EN),('layer-metric-objects',METRIC_EN)],status='complete_with_scope_issue',scope='定义解释已完整；原文未规定空显著集合的平均、空并集 IoU、零强度比值或零方差稳定性的取值，不补造约定。',en_scope='The definitions are fully explained; the source specifies no convention for averages over an empty salient family, IoU of an empty union, zero-strength ratios, or stability with zero variance.',issues=['layer-issue-zero-metrics'])
step(r,'逐项保留共享与残差强度的支持','Retain the supports of shared and residual strengths',r'''令 $s_S=s(A_l(S),A_L(S))$。原 Eq.(7) 的 overlap 只遍历共同显著支持；forget 遍历本层全部显著支持，new 遍历末层全部显著支持。后两项仍减去由实际两个系数定义的 $s_S$，并不只在共同显著集合内定义 $s_S$。OR 指标将 $A$ 与 $\Omega_{and}$ 换成 $O$ 与 $\Omega_{or}$。''',r'''Let $s_S=s(A_l(S),A_L(S))$. In Eq.(7), overlap ranges only over the common salient support, whereas forget ranges over the entire current-layer salient support and new over the entire final-layer salient support. The latter two still subtract $s_S$ defined from the two actual coefficients; $s_S$ is not defined only on the common salient family. Replace $A,\Omega_{and}$ by $O,\Omega_{or}$ for OR metrics.''',r'\operatorname{overlap}_{l,m}=\sum_{S\in\Omega_l\cap\Omega_L}|s_S|,\quad\operatorname{forget}_{l,m}=\sum_{S\in\Omega_l}|A_l(S)-s_S|,\quad\operatorname{new}_{l,m}=\sum_{S\in\Omega_L}|A_L(S)-s_S|.')
step(r,'定义比例和跨模型交并比','Define ratios and cross-model IoU',r'''completeness 是 overlap 除以末层 all，redundancy 是 forget 除以本层 all。两者是本定义下的数值指标；不能从术语自动推出特征完备性或泛化保证。IoU 对同阶集合族计数，$\mathcal A\cup\mathcal B$ 非空时介于 $0,1$；空并集时原分式为 $0/0$。''',r'''Completeness divides overlap by the final-layer all strength, and redundancy divides forget by the current-layer all strength. These are numerical metrics under the stated definitions; their names do not imply feature completeness or a generalization guarantee. IoU counts same-order coalition families and lies in $[0,1]$ when the union is nonempty; an empty union gives the source fraction $0/0$.''',r'\operatorname{completeness}_{l,m}=\frac{\operatorname{overlap}_{l,m}}{\operatorname{all}_{L,m}},\qquad\operatorname{redundancy}_{l,m}=\frac{\operatorname{forget}_{l,m}}{\operatorname{all}_{l,m}}.')
step(r,'定义真实随机噪声下的稳定性','Define stability under genuine random noise',r'''令 $\epsilon\sim\mathcal N(0,\sigma^2I)$，$\mu_l(S,x)=\mathbb E_\epsilon A_l(S\mid x+\epsilon)$，$\nu_l(S,x)=\operatorname{Var}_\epsilon A_l(S\mid x+\epsilon)$。原式先对显著 $S$ 平均 $|\mu_l|/\sqrt{\nu_l}$，再对样本平均；它不是把两层的交互系数当随机噪声，也不是学习残差 $\delta_T$。需要存在相应矩和正方差才能按实数分式解释；零方差、空集合平均原文未另定。''',r'''Let $\epsilon\sim\mathcal N(0,\sigma^2I)$, $\mu_l(S,x)=\mathbb E_\epsilon A_l(S\mid x+\epsilon)$, and $\nu_l(S,x)=\operatorname{Var}_\epsilon A_l(S\mid x+\epsilon)$. The source first averages $|\mu_l|/\sqrt{\nu_l}$ over salient $S$ and then over samples. It does not treat layer coefficients as random noise or identify the perturbation with learned residual $\delta_T$. The relevant moments and positive variance are needed for the real fraction; no zero-variance or empty-family convention is supplied.''',r'\operatorname{stability}_{and}^{l,m}=\mathbb E_x\mathbb E_{S\in\Omega_{and}^{l,m}}\left[\frac{|\mu_l(S,x)|}{\sqrt{\nu_l(S,x)}}\right].')
flush()

r=setr('layer-strength-decomposition','Eq.(8)：阈值支持下的强度分解反例','Eq.(8): a counterexample with thresholded supports',r'\operatorname{all}_{l,m}=\operatorname{overlap}_{l,m}+\operatorname{forget}_{l,m},\qquad\operatorname{all}_{L,m}=\operatorname{overlap}_{l,m}+\operatorname{new}_{l,m}',r'''原 Eq.(8) 声称 Eqs.(6),(7) 的三项形成上述两个总强度分解。脚注 7 的显著阈值是该层最大 AND/OR 强度的 $0.05$ 倍；脚注 8 按层输出差的样本平均绝对值归一化。''','单个系数的幅度分解成立；原显著集合求和的支持不同，使总式失败。','The scalar magnitude decomposition holds, but the differing salient supports make the printed aggregate identity fail.',defs=[('layer-objects',COMMON_ZH),('layer-metric-objects',METRIC_ZH)],en_defs=[('layer-objects',COMMON_EN),('layer-metric-objects',METRIC_EN)],status='blocked_by_false_statement',scope='保留原 Eq.(8) 及其原阈值/归一化；给出满足这些设置、且纯 AND 分解全局 L1 最优的有限游戏反例。标量等式和原总式分别登记。',en_scope='Eq.(8) and its original threshold/normalization are retained. A finite-game counterexample satisfies those settings and uses globally L1-optimal pure AND splits. The scalar identity and the printed aggregate claim are recorded separately.',issues=['layer-issue-strength-8'])
step(r,'证明单系数幅度分解','Prove the scalar magnitude decomposition',r'''若两系数异号，共享 $s=0$，所以 $|a|=|s|+|a-s|$。若同号，$s$ 与 $a$ 同号且 $|s|\le|a|$，因此 $|a-s|=|a|-|s|$。同理对 $b$ 成立。原总式需要把 $|s_S|$ 在相同求和支持上收回，而 overlap 仅包含共同显著支持；遗漏支持中的非零共享项就是差额。''',r'''For opposite signs, the shared value is $s=0$, so $|a|=|s|+|a-s|$. For matching signs, $s$ has the sign of $a$ and $|s|\le|a|$, hence $|a-s|=|a|-|s|$. The same holds for $b$. The aggregate claim must collect $|s_S|$ on the same support, but overlap includes only the common salient support. Nonzero shared terms outside that support form the discrepancy.''',r'|a|=|s(a,b)|+|a-s(a,b)|,\quad |b|=|s(a,b)|+|b-s(a,b)|.',refs=refs('Harsanyi.Layerwise.scalar_strength_decomposition','仅标量恒等式形式化，不代表原 Eq.(8) 总式成立。','Only the scalar identity is formalized; this does not prove Eq.(8).'))
step(r,'构造归一化且最优的两个游戏','Construct normalized, optimal layer games',r'''取 $N=\{1,2\}$，数据分布只有一个样本 $x=(1,1)$，输入基线 $r=(0,0)$。设 $v^{(l)}(z)=(z_1+z_2)/2$、$v^{(L)}(z)=(z_1+100z_2)/101$，故 $g_l(U)=\tfrac12\mathbf1_{1\in U}+\tfrac12\mathbf1_{2\in U}$，$g_L(U)=\tfrac1{101}\mathbf1_{1\in U}+\tfrac{100}{101}\mathbf1_{2\in U}$。可作为线性探针的 log-odds，令残差为零。取 $\gamma_k=g_k/2$，则 $a_k=g_k,o_k=0$；唯一非零交互是这两个单点系数。两层 $g_k(N)-g_k(\varnothing)=1$，脚注 8 的归一化因子都是 $1$。任意精确分解的非空交互和等于 $1$，三角不等式使 L1 至少为 $1$；此纯 AND 分解达到 $1$，所以它不是非最优分解的伪反例。''',r'''Take $N=\{1,2\}$, a one-sample data distribution at $x=(1,1)$, and baseline $r=(0,0)$. Set $v^{(l)}(z)=(z_1+z_2)/2$ and $v^{(L)}(z)=(z_1+100z_2)/101$. Thus $g_l(U)=\tfrac12\mathbf1_{1\in U}+\tfrac12\mathbf1_{2\in U}$ and $g_L(U)=\tfrac1{101}\mathbf1_{1\in U}+\tfrac{100}{101}\mathbf1_{2\in U}$. These can be linear-probe log-odds with zero residual. Choosing $\gamma_k=g_k/2$ gives $a_k=g_k,o_k=0$; the only nonzero dividends are the two singleton coefficients. Both layers satisfy $g_k(N)-g_k(\varnothing)=1$, so footnote 8’s normalization factors are $1$. In every exact split the nonempty dividends sum to $1$, so the triangle inequality bounds L1 below by $1$. The pure AND split attains $1$, establishing global optimality.''',r'\sum_{S\ne\varnothing}(|A_k(S)|+|O_k(S)|)\ge\left|\sum_{S\ne\varnothing}(A_k(S)+O_k(S))\right|=|g_k(N)-g_k(\varnothing)|=1.')
step(r,'核对真实阈值并计算冲突','Check the actual thresholds and compute the failure',r'''取阶数 $m=1$。最大强度分别为 $1/2$、$100/101$，所以 $\tau_l=1/40$、$\tau_L=5/101$。原严格阈值给 $\Omega_l=\{\{1\},\{2\}\}$、$\Omega_L=\{\{2\}\}$。共享单点强度为 $s_{\{1\}}=1/101$、$s_{\{2\}}=1/2$。故 $\operatorname{all}_{l,1}=1$，overlap 为 $1/2$，forget 为 $1/2-1/101=99/202$，二者和为 $100/101\ne1$。末层 new 为 $100/101-1/2=99/202$，与 overlap 的和也为 $100/101\ne\operatorname{all}_{L,1}=100/101$？此处末层 all 只遍历显著 $\{2\}$，确为 $100/101$，所以第二等式在本例成立；第一等式已足以反驳原联立分解，不把第二式误报为反例。''',r'''Take order $m=1$. The maximal strengths are $1/2$ and $100/101$, so $\tau_l=1/40$ and $\tau_L=5/101$. The strict source threshold gives $\Omega_l=\{\{1\},\{2\}\}$ and $\Omega_L=\{\{2\}\}$. Shared singleton strengths are $s_{\{1\}}=1/101$ and $s_{\{2\}}=1/2$. Thus $\operatorname{all}_{l,1}=1$, overlap is $1/2$, and forget is $1/2-1/101=99/202$; their sum is $100/101\ne1$. Final-layer new is $100/101-1/2=99/202$, and its sum with overlap is $100/101$. The final-layer all metric also counts only salient $\{2\}$ and equals $100/101$, so the second identity holds in this witness. The first identity already refutes the joint claim; the second is not misreported as failing.''',r'\operatorname{overlap}_{l,1}+\operatorname{forget}_{l,1}=\frac12+\frac{99}{202}=\frac{100}{101}\ne1=\operatorname{all}_{l,1}.')
# Remove an awkward self-correction from the authoritative Chinese paragraph.
r['proof_steps'][-1]['body_md']=r['proof_steps'][-1]['body_md'].replace('，与 overlap 的和也为 $100/101\\ne\\operatorname{all}_{L,1}=100/101$？此处末层 all 只遍历显著 $\\{2\\}$，确为 $100/101$，所以第二等式在本例成立；','，与 overlap 的和为 $100/101$；末层 all 只遍历显著 $\\{2\\}$，也等于 $100/101$，所以第二等式在本例成立；')

r=setr('layer-binomial-symmetry','互补阶数的组合数量相同','Complementary orders have equal coalition counts',r'\binom nm=\binom n{n-m}\qquad(0\le m\le n)',r'''第 8 页未编号比较：当 $m<n/2$ 时，$m$ 阶和 $(n-m)$ 阶均有相同数量 $\binom nm$ 的可能变量组合。原文随后报告低阶更易泛化，这是经验结论，不是本计数等式的推论。''','补集是固定大小集合族之间的双射。','Complementation is a bijection between the two fixed-cardinality families.',assumptions=[r'$n=|N|$，整数 $0\le m\le n$；原比较另取 $m<n/2$。'],en_assumptions=[r'$n=|N|$ and integer $0\le m\le n$; the source comparison additionally uses $m<n/2$.'])
step(r,'构造互逆的补集映射','Construct the inverse complement maps',r'''若 $|S|=m$，$|N\setminus S|=n-m$；再取补集回到 $S$。因此 $S\mapsto N\setminus S$ 是 $m$ 元子集与 $(n-m)$ 元子集的双射，计数相同，得到二项式恒等式。空集与总体、$m=n/2$ 的情况同样成立。''',r'''If $|S|=m$, then $|N\setminus S|=n-m$, and complementing again returns $S$. Thus $S\mapsto N\setminus S$ bijects the size-$m$ and size-$(n-m)$ families, proving the binomial identity. The empty/full cases and $m=n/2$ are included.''',r'\#\{S\subseteq N:|S|=m\}=\#\{S\subseteq N:|S|=n-m\}.',refs=refs('Harsanyi.Layerwise.complementary_order_count','声明核验计数恒等式，未证明经验泛化比较。','The declaration checks the counting identity, not the empirical generalization comparison.'))

r=setr('layer-shapley-and-or','Appendix B：Shapley 的 AND/OR 均分','Appendix B: Shapley sharing of AND/OR dividends',r'\varphi_g(i)=\sum_{\substack{S\subseteq N\\i\in S}}\frac{A(S)+O(S)}{|S|}',r'''附录 B perspective 2 写 $\phi(i)=\sum_{S\subseteq N:S\ni i}\frac1{|S|}I_{and}(S\mid x)+\sum_{S\subseteq N:S\ni i}\frac1{|S|}I_{or}(S\mid x)$，解释交互平均分配给成员。当地没有从阶乘边际定义展开的作者证明；以下是项目完整补证。''','从经典阶乘边际出发，按变量在排列中最后/最先出现计数。','Start from the classical factorial marginal and count last/first occurrences in permutations.',assumptions=[r'$i\in N$；同一固定分解 $g=a+o$；不需零输出基线。'],en_assumptions=[r'$i\in N$; a single fixed split $g=a+o$; no zero output baseline is required.'],defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)])
step(r,'明确阶乘权重与掩码边际','Specify factorial weights and the masked marginal',r'''令 $n=|N|$，$U\subseteq N\setminus\{i\}$，$w(U)=|U|!(n-|U|-1)!/n!$。经典 Shapley 是 $\sum_Uw(U)[g(U\cup\{i\})-g(U)]$。固定重构式相减后，AND 项留下包含 $i$ 且其他成员都在 $U$ 的集合；OR 项留下包含 $i$ 且其他成员都不在 $U$ 的集合。基线抵消。''',r'''Let $n=|N|$, $U\subseteq N\setminus\{i\}$, and $w(U)=|U|!(n-|U|-1)!/n!$. Classical Shapley is $\sum_Uw(U)[g(U\cup\{i\})-g(U)]$. Subtracting the fixed reconstruction formulas retains AND coalitions containing $i$ whose other members are in $U$, and OR coalitions containing $i$ whose other members are outside $U$. The baseline cancels.''',r'g(U\cup\{i\})-g(U)=\sum_{L\subseteq U}A(L\cup\{i\})+\sum_{L\subseteq N\setminus(U\cup\{i\})}O(L\cup\{i\}).')
step(r,'按排列首尾计数均分权重','Count equal shares by first and last positions',r'''均匀随机排列中，$U$ 恰为 $i$ 的前驱集的概率是 $w(U)$。固定 $S\ni i$ 时，AND 被 $i$ 激活恰当 $i$ 最后出现在 $S$ 中，OR 被 $i$ 激活恰当 $i$ 最先出现。$S$ 中各成员处于最先或最后位置的事件互斥且等概率，并覆盖全部排列，所以各概率为 $1/|S|$。这对正负系数均成立。''',r'''In a uniform random permutation, $w(U)$ is the probability that $U$ is exactly the predecessor set of $i$. For fixed $S\ni i$, $i$ activates the AND term precisely when it is last within $S$, and activates the OR term precisely when it is first. The members’ first-position events, or last-position events, are disjoint, equiprobable, and exhaust all permutations; each has probability $1/|S|$. This counting applies to coefficients of either sign.''',r'\mathbb P(i\text{ is last in }S)=\mathbb P(i\text{ is first in }S)=\frac1{|S|}.')
step(r,'交换有限和并合成结论','Exchange finite sums and combine the contributions',r'''固定每个交互的激活概率后，交换有限交互和与排列平均，得到两种交互分别均分，合并即原式。所有被计入的 $S$ 都含 $i$，因此非空，分母正。Lean 直接走等价的阶乘权重有限和路线，核验同一最终结论，并非单独形式化本段排列叙述。''',r'''After determining each activation probability, exchange the finite dividend sum and permutation average. Both interaction types are shared equally, and adding them yields the stated formula. Every included $S$ contains $i$, so its denominator is positive. Lean uses the equivalent finite factorial-weight route to verify this final equality; it does not separately formalize the permutation narrative.''',r'\varphi_g(i)=\sum_{S\ni i}\frac{A(S)}{|S|}+\sum_{S\ni i}\frac{O(S)}{|S|}.',refs=refs('Harsanyi.Layerwise.shapley_and_or','实际声明从经典阶乘边际定义推出固定分解的均分结论。','The declaration derives the fixed-split sharing formula from the classical factorial marginal definition.'))

r=setr('layer-complement-duality','Eqs.(11)–(13)：补集对偶及原坐标错式','Eqs.(11)–(13): complementary duality and the coordinate error',r'O(S)=-I_h(S),\quad h(T)=o(N\setminus T)\quad(S\ne\varnothing)',r'''附录 C 原 Eq.(11) 写 $(x_{N\setminus T})_i=x_i$ 当 $i\in N\setminus T$、$b_i$ 当 $i\in T$；Eq.(12) 却写 $(x'_T)_i=x_i$ 当 $i\in T$、$b_i$ 当 $i\in N\setminus T$。Eq.(13) 据此断言 $v(x_{N\setminus T})=v(x'_T)$，再得 $I_{or}(S\mid x)=-I_{and}(S\mid x')$。原两坐标定义和原错误等式均保留。''','游戏层面的补集对偶有效；原 Eq.(12) 所定义的样本不等于 Eq.(11) 的样本。','Complementary duality at the game level is valid; the sample defined in Eq.(12) does not equal the one in Eq.(11).',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)],status='complete_with_scope_issue',scope='补集游戏的负 Möbius 等式已完整证明；原 Eq.(13) 对 Eq.(12) 字面坐标的中间等式有反例，不把改写坐标后的新定义冒充原命题。',en_scope='The negative Möbius identity for the complementary game is fully proved. The intermediate Eq.(13) equality under Eq.(12)’s literal coordinates has a counterexample; a corrected coordinate definition is not substituted into the original proposition.',issues=['layer-issue-coordinate-13'])
step(r,'直接展开补集游戏变换','Expand the complementary-game transform directly',r'''取 $h(T)=o(N\setminus T)$，则 $I_h(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}o(N\setminus T)$。对非空 $S$，与 OR 定义逐项相反，所以 $O(S)=-I_h(S)$。这是对同一 OR 分量的代数恒等式，不需要它是神经网络输出或具有稀疏性。''',r'''Set $h(T)=o(N\setminus T)$. Then $I_h(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}o(N\setminus T)$. For nonempty $S$, this is termwise the negative of the OR definition, proving $O(S)=-I_h(S)$. This algebraic identity concerns the same OR component and requires neither a neural-network representation nor sparsity.''',r'O(S)=-I_h(S)\quad(S\ne\varnothing).')
step(r,'给出原坐标等式反例','Give a counterexample to the source coordinate equality',r'''取 $N=\{1\}$、$x_1=1$、输入基线 $r_1=0$、$T=\{1\}$，并令 $v(z)=z_1$。Eq.(11) 的样本为 $0$，Eq.(12) 的样本为 $1$，所以两输出是 $0$ 与 $1$。因此 Eq.(13) 中由原 Eq.(12) 得到的第二等号错误。''',r'''Take $N=\{1\}$, $x_1=1$, input baseline $r_1=0$, $T=\{1\}$, and $v(z)=z_1$. The sample in Eq.(11) is $0$, whereas the sample in Eq.(12) is $1$, so the outputs are $0$ and $1$. The second equality in Eq.(13), obtained from the printed Eq.(12), is therefore false.''',r"v(x_{N\setminus T})=0\ne1=v(x'_T).")
step(r,'解释正确反向掩码的作用域','Explain the scope of a correct reversed mask',r'''如果另设反向输入为 $r$、其输入基线为 $x$，其保留 $T$ 的样本才具有在 $T$ 上取 $r_i$、其余取 $x_i$ 的坐标，等于 $x_{N\setminus T}$。这说明原证明可以怎样写成正确补集游戏，但原 Eq.(12) 本身不能当作已成立的定义等价。空集 OR 还使用特设基线，不纳入负变换公式。''',r'''If a separate reversed input is $r$ with input baseline $x$, retaining $T$ gives coordinates $r_i$ on $T$ and $x_i$ elsewhere, exactly $x_{N\setminus T}$. This explains the correct complementary-game proof, but it does not make the printed Eq.(12) definition equivalent. The special empty OR baseline is also excluded from the negative-transform formula.''')
flush()

r=setr('layer-or-sparsity-inheritance','Appendix C：OR 稀疏外引的条件缺口','Appendix C: missing conditions in the OR sparsity inference',r'O(S)=-I_{T\mapsto o(N\setminus T)}(S)\quad(S\ne\varnothing)',r'''附录 C 最后段由 OR 可视为特殊 AND，推出 Ren 等已证明的 AND 稀疏性也证明 OR 稀疏性，并称大多数训练好的 DNN 只编码少量 OR 交互。原文没有检验反向 OR 分量满足外引定理条件。''','变换恒等式只识别系数，不能自动运输关于特定模型类的稀疏定理。','The transform identity identifies coefficients but does not automatically transport a sparsity theorem for a particular model class.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)],status='complete_with_scope_issue',scope='完整解释原外引推断与必要适配。未证明学习 OR 分量的补集游戏满足 Sparse 原条件，也没有在其全部原条件下反驳外引定理。',en_scope='The external inference and required adaptation are fully explained. The complemented learned OR component is not shown to satisfy the Sparse theorem’s conditions; the cited theorem is also not refuted under all of its original assumptions.',issues=['layer-issue-sparse-transfer','layer-issue-coordinate-13'])
step(r,'区分变换事实与模型条件','Separate the transform identity from model conditions',r'''对任意 OR 分量，负 Möbius 变换等式成立，所以 OR 系数的数量等于该补集游戏非零 AND 系数的数量。这个结论并未限制数量。有限集合函数可以任意指定全部非空 Möbius 系数，再由反演重构，故变换关系本身不能证明只有少量非零项。''',r'''For any OR component, the negative Möbius identity holds, so its nonzero OR count equals the nonzero AND count of the complemented game. This imposes no upper bound. One may prescribe all nonempty Möbius coefficients of a finite game and reconstruct it by inversion; the transform relation alone therefore cannot establish a small nonzero count.''')
step(r,'列出外引必须核对的实例','Identify the instances required by the external theorem',r'''必须对游戏 $h(T)=o(N\setminus T)$ 检验外引的模型类、高阶交互限制、各阶平均输出条件和参数范围；仅对总输出 $g$ 作这些观察仍不够。取补集会把保留变量数 $m$ 变为 $n-m$，其平均输出的单调方向可能反转。学习分解 $\gamma$ 也可改变两分量，而不改变 $g$。因此当前归类为外引范围未完成，不新增条件强行证明原陈述。''',r'''The model class, high-order restrictions, mean-output conditions by order, and parameter ranges must be checked for $h(T)=o(N\setminus T)$. Observing them for the total output $g$ is insufficient. Complementation changes retained count $m$ to $n-m$ and may reverse the direction of mean-output monotonicity. The learned split $\gamma$ can also change both components while leaving $g$ unchanged. The entry is therefore an unresolved external-scope inference, without adding conditions to force a proof.''')

r=setr('layer-noise-ratio','Appendix L：不同阶数的噪声比例观察','Appendix L: observed noise ratios across orders',r'\operatorname{Ratio}^{\epsilon}_S=\frac{\|x_S-x_S^{\epsilon}\|_2}{\|x_S\|_2}',r'''附录 L 在 CIFAR-10 语义块上加高斯输入扰动，计算噪声强度与交互模式信号强度的比值；Figure 12 报告各阶该比值中位数近似相同，随后解释高阶交互稳定性差并非由观察到的噪声比例较大引起。原文没有解析定理或全模型保证。''','保留测量指标与实验推断，区分输入强度比和交互随机方差。','Retain the measured metric and empirical inference, distinguishing input intensity ratios from random interaction variance.',status='complete_empirical_explanation')
step(r,'定义输入模式的信号噪声比','Define the input-pattern noise-to-signal ratio',r'''$x_S^\epsilon$ 表示扰动后模式，分母是该模式的输入欧氏范数；这不是交互均值 $\mu_l$ 或方差 $\nu_l$。输入范数为零时原比值未定义。高斯扰动的总输入能量可随坐标数变化，但其相对值仍依赖输入范数、语义块维数和扰动方差。''',r'''$x_S^\epsilon$ denotes the perturbed pattern, and the denominator is its input Euclidean norm; neither is the interaction mean $\mu_l$ or variance $\nu_l$. The source ratio is undefined for a zero input norm. Total Gaussian input energy may vary with coordinate count, while the relative value also depends on input norm, semantic-block dimension, and perturbation variance.''')
step(r,'界定图示比较的结论','Delimit the conclusion of the plotted comparison',r'''Figure 12 的中位数接近是指定样本与噪声设置的经验发现。它支持该实验中的相对噪声解释，不推导任意函数的交互信号随阶数线性增长，也不证明全部阶数的概率分布相同。稳定性下降仍是 Figures 5,9 所报告的经验现象。''',r'''The similar medians in Figure 12 are an observation for the specified samples and noise setting. They support that experiment’s relative-noise interpretation, but do not establish linear interaction-signal growth with order for arbitrary functions or identical distributions at all orders. The decline in stability remains the empirical finding reported in Figures 5 and 9.''')

r=setr('layer-singleton-merge','Appendix M.4：一阶 AND/OR 合并','Appendix M.4: merging first-order AND/OR effects',r'A(\{i\})\mathbf1_{i\in T}+O(\{i\})\mathbf1_{i\in T}=[A(\{i\})+O(\{i\})]\mathbf1_{i\in T}',r'''附录 M.4 最后段：实验为方便把一阶 OR 交互并入一阶 AND，新的单点 AND 效应是两者之和，因为单一变量的 AND/OR 激活关系相同。''','两个单点激活事件相同，合并保持每个掩码的输出贡献。','The singleton activation events coincide, so merging preserves their contribution on every mask.',defs=[('layer-objects',COMMON_ZH)],en_defs=[('layer-objects',COMMON_EN)])
step(r,'核对单点激活事件','Check the singleton activation events',r'''对任意 $T\subseteq N$，$\{i\}\subseteq T$ 当且仅当 $i\in T$，且 $\{i\}\cap T\ne\varnothing$ 也当且仅当 $i\in T$。因此两个指示函数相同。''',r'''For every $T\subseteq N$, $\{i\}\subseteq T$ if and only if $i\in T$, and $\{i\}\cap T\ne\varnothing$ also if and only if $i\in T$. The activation indicators coincide.''',r'\mathbf1_{\{i\}\subseteq T}=\mathbf1_{\{i\}\cap T\ne\varnothing}=\mathbf1_{i\in T}.')
step(r,'合并系数并说明表示变化','Merge the coefficients and explain the representation change',r'''相同指示函数下两系数相加即得原结论；正负系数也可以合并。此操作改变 AND/OR 表示与单点的显著性计数，但不改变单点对任何掩码的总输出贡献。多元集合的包含事件与相交事件不同，所以不能把此操作推广为任意阶的同样合并。''',r'''Adding the two coefficients under their common indicator proves the claim, including coefficients of either sign. This changes the AND/OR representation and may change singleton saliency counts, but preserves the singleton’s total contribution on every mask. Containment and intersection differ for larger coalitions, so this merge cannot be generalized to all orders.''',r'(a+o)\mathbf1_{i\in T}=a\mathbf1_{\{i\}\subseteq T}+o\mathbf1_{\{i\}\cap T\ne\varnothing}.',refs=refs('Harsanyi.Layerwise.singleton_merge','实际声明核验任意有限掩码上两个单点贡献的合并。','The declaration checks merging the two singleton contributions on every finite mask.'))

r=setr('layer-experiments','Figures 1–12：经验观察与实验设置','Figures 1–12: empirical observations and experimental settings',r'\operatorname{order}(S)=|S|',r'''正文与附录的图表报告稀疏交互、层间共享/新增/忘记、跨模型 IoU、输入噪声稳定性、残差参数比较及噪声比例。它们是训练模型与所选样本的实验结果，不是新增数学定理。''','按图示范围保留经验结论，避免把图表或算法描述算作已证明数学目标。','Retain empirical conclusions within each experiment’s scope, without counting plots or procedures as proved mathematical targets.',status='complete_empirical_explanation')
step(r,'说明样本和模型范围','Specify samples and model scope',r'''Figures 1,2 展示交互模式和稀疏强度；Figures 3,7,10 对图像、语言和表格任务跟踪层间强度；Figures 4,8 比较跨模型 IoU；Figures 5,9 比较噪声稳定性；Figure 6 展示交互与特征归因的解释视角；Figures 11,12 分别比较残差上限与噪声比例。MNIST 的主要计算选 $10$ 个前景块、CIFAR-10 选 $12$ 个中心块、SST-2 选 $10$ 个词。附录 M 给出样本数、探针训练与中间层选择。''',r'''Figures 1 and 2 illustrate patterns and sparse strengths. Figures 3, 7, and 10 track layerwise strengths on image, language, and tabular tasks; Figures 4 and 8 compare cross-model IoU; Figures 5 and 9 compare noise stability. Figure 6 contrasts interaction and feature-attribution perspectives. Figures 11 and 12 compare residual limits and noise ratios. The main calculations use $10$ foreground blocks for MNIST, $12$ central blocks for CIFAR-10, and $10$ words for SST-2. Appendix M gives sample counts, probe training, and selected intermediate layers.''')
step(r,'保留趋势与其数学限制','Retain the trends and their mathematical limits',r'''论文观察低阶交互往往更强、更易跨模型共享且更稳定；中间层学习最终所需交互，部分高层丢弃冗余高阶交互。不同网络存在不同轨迹，附录 K 逐类讨论。图中强度分解还依赖原 Eq.(8)，该式的支持问题另有反例；经验图不能反过来使该恒等式成立。''',r'''The paper observes that low-order interactions are often stronger, more shared across models, and more stable; intermediate layers acquire interactions used finally, while some later layers discard redundant high-order interactions. Different architectures show different trajectories, discussed in Appendix K. The plotted strength decomposition also relies on Eq.(8), whose support issue has a separate counterexample. An empirical plot cannot establish that identity.''')

r=setr('layer-external-properties','Section 2：外引性质与解释证据','Section 2: cited properties and explanatory evidence',r'I_f(S)=\sum_{T\subseteq S}(-1)^{|S|-|T|}f(T)',r'''Section 2 外引交互稀疏、跨样本/模型迁移、分类判别力、七条数学性质、表示瓶颈、学习难度及低阶泛化。当地没有这些结论的完整作者证明。''','外引定理、经验现象和解释主张分别标明，原证明不在本篇的不能冒充本地证明。','Distinguish cited theorems, observations, and interpretive claims; results proved elsewhere are not treated as local author proofs.',status='complete_external_reference_explanation')
step(r,'区分各类引用所支持的事实','Distinguish the facts supported by the citations',r'''稀疏性既有经验观察也有在特定条件下的部分理论；迁移和判别能力是 cited experiments 的证据；交互七性质是其他论文的代数结果；表示瓶颈和学习难度依赖各自模型条件。当前条目只完整整理本篇引用关系，不把这些引用合并成对所有 DNN 的统一定理。''',r'''Sparsity has both empirical observations and partial theory under particular conditions. Transfer and discrimination are supported by cited experiments; the seven interaction properties are algebraic results in other papers; representation bottlenecks and learning difficulty depend on their respective model assumptions. This entry records the local citation relationships without combining them into one theorem for all DNNs.''')
step(r,'保留知识解释的边界','Retain the boundary of the knowledge interpretation',r'''作者明确承认没有理论保证显著交互完全拟合人类认知中的“知识”。精确重构保证的是给定掩码游戏的输出表示，而非某一认知语义唯一成立。公共代数库可复用相同有限集合定义；跨论文的稀疏或统计结论须另核前提。''',r'''The authors explicitly acknowledge the absence of a theory guaranteeing that salient interactions exactly match knowledge in human cognition. Exact reconstruction guarantees an output representation of the specified masked game, rather than a unique cognitive meaning. The public algebra library can reuse the same finite-set definitions, while sparsity or statistical results need separate cross-paper assumption checks.''')
flush()
